request.query:
query GetDefinitionProblems($kind: DefinitionKind!) {
  definitionProblems(kind: $kind) {
    kind
    definitionId
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    dependencyChain
    __typename
  }
}

query GetAllWorkspaces {
  workspaces {
    __typename
    workspaceId
    name
    displayName
    config
    workspaceRootPath
    absolutePath
    kind
    isTemp
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      closed_task_executions
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}

query GetApplicationsCapability {
  applicationsCapability {
    ...ApplicationsCapabilityFields
    __typename
  }
}

fragment ApplicationsCapabilityFields on ApplicationsCapability {
  enabled
  scope
  settingKey
  source
  __typename
}

mutation UpdateAgentOrgDefinition($input: UpdateAgentOrgDefinitionInput!) {
  updateAgentOrgDefinition(input: $input) {
    ...AgentOrgDefinitionFields
    __typename
  }
}

fragment AgentOrgDefinitionFields on AgentOrgDefinition {
  id
  name
  description
  instructions
  category
  avatarUrl
  revision
  handoffs {
    from
    to
    rules
    __typename
  }
  members {
    memberName
    ref
    refType
    refScope
    __typename
  }
  defaultLaunchConfig {
    llmModelIdentifier
    runtimeKind
    llmConfig
    __typename
  }
  loadIssues {
    kind
    definitionId
    name
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    __typename
  }
  __typename
}

mutation UpdateAgentOrgDefinition($input: UpdateAgentOrgDefinitionInput!) {
  updateAgentOrgDefinition(input: $input) {
    ...AgentOrgDefinitionFields
    __typename
  }
}

fragment AgentOrgDefinitionFields on AgentOrgDefinition {
