    memberName
    ref
    refType
    refScope
    __typename
  }
  defaultLaunchConfig {
    llmModelIdentifier
    runtimeKind
    llmConfig
    __typename
  }
  loadIssues {
    kind
    definitionId
    name
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    __typename
  }
  __typename
}
